import React, { useState, useRef } from 'react';
import PropTypes from 'prop-types';

const ChunkUpload = (props) => {
    const [progress, setProgress] = useState(0);
    const [status, setStatus] = useState("idle");  // ✅ NEW
    const fileInputRef = useRef(null);

    const uploadFile = async (file) => {
        const chunkSize = props.chunk_size || 5 * 1024 * 1024;
        let offset = 0;

        setStatus("uploading");  // ✅ start upload

        try {
            const initRes = await fetch('/upload-init', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({ 
                    filename: file.name,
                    component_id: props.id
                })
            });

            const { upload_id } = await initRes.json();

            while (offset < file.size) {
                const chunk = file.slice(offset, offset + chunkSize);
                const formData = new FormData();

                formData.append('upload_id', upload_id);
                formData.append('chunk', chunk);

                await fetch('/upload-chunk', {
                    method: 'POST',
                    body: formData
                });

                offset += chunkSize;

                const prog = offset / file.size;
                setProgress(prog);

                if (props.setProps) {
                    props.setProps({ progress: prog });
                }
            }

            const completeRes = await fetch('/upload-complete', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({ upload_id })
            });

            const result = await completeRes.json();

            if (props.setProps) {
                props.setProps({
                    file_info: result.filepath,
                    progress: 1
                });
            }

            // ✅ Reset UI after short delay
            setTimeout(() => {
                setProgress(0);
                setStatus("idle");
            }, 800);

        } catch (err) {
            console.error("Upload error:", err);
            setStatus("idle");  // fallback
        }
    };

    const handleClick = () => {
        fileInputRef.current.click();
    };

    const handleDrop = (e) => {
        e.preventDefault();
        const file = e.dataTransfer.files[0];
        if (file) uploadFile(file);
    };

    const handleDragOver = (e) => e.preventDefault();

    // ✅ UI text logic
    let content;
    if (status === "uploading") {
        content = `Progress: ${(progress * 100).toFixed(1)}%`;
    } else {
        content = (
            <>
                Drag and Drop or <strong>Select File</strong>
            </>
        );
    }

    return (
        <div
            className={`chunk-upload-box ${props.className || ""}`}
            style={props.style}
            onClick={handleClick}
            onDrop={handleDrop}
            onDragOver={handleDragOver}
        >
            {content}

            <input
                type="file"
                ref={fileInputRef}
                style={{ display: 'none' }}
                onChange={(e) => {
                    const file = e.target.files[0];
                    if (file) uploadFile(file);
                }}
            />
        </div>
    );
};


ChunkUpload.propTypes = {
    id: PropTypes.string,
    file_info: PropTypes.object,
    progress: PropTypes.number,
    chunk_size: PropTypes.number,
    className: PropTypes.string,
    style: PropTypes.object,
    setProps: PropTypes.func
};

export default ChunkUpload;